import json, hashlib, re, subprocess
H = re.compile(r'[0-9a-f]{64}')
def sh(b): return hashlib.sha256(b).hexdigest()
def git(*a): return subprocess.run(['git', *a], capture_output=True).stdout
changed = git('diff', '--name-only', '7d62165a^', '7d62165a').decode().split()
print('changed files:', len(changed))
for c in changed: print('  ', c)
old = {}
for c in changed:
    r = subprocess.run(['git', 'show', '7d62165a^:' + c], capture_output=True)
    if r.returncode == 0: old[sh(r.stdout)] = c
st = open('benchmark/preparation-status.json').read()
vals = H.findall(st)
hits = [(v, old[v]) for v in vals if v in old]
print('status 64-hex values:', len(vals), 'matching old hashes of changed files:', len(hits))
for h in hits: print('  ', h)
print('check_xml_keys sha:', sh(open('benchmark/scripts/check_xml_keys.py', 'rb').read())[:8])
p = json.load(open('benchmark/writing/input-pins.json'))['protected_inputs_sha256']
bad = [k for k, v in p.items() if sh(open(k, 'rb').read()) != v]
print('input-pins entries:', len(p), 'bad:', bad)
prep = json.load(open('benchmark/preparation.json'))
pairs = []
def walk(o):
    if isinstance(o, dict):
        if 'path' in o and 'sha256' in o: pairs.append((o['path'], o['sha256']))
        for v in o.values(): walk(v)
    elif isinstance(o, list):
        for v in o: walk(v)
walk(prep)
bad2 = []
for pa, h in pairs:
    try:
        if sh(open(pa, 'rb').read()) != h: bad2.append(pa)
    except Exception as e: bad2.append((pa, str(e)))
print('preparation entries:', len(pairs), 'bad:', bad2)
